# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/se-bmk-intern/pfr" ] || echo "WARNING: submission missing: /home/workspace/se-bmk-intern/pfr"

